-- European Union deep-dive content translations (ES/DE/FR)

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Marco escalonado a nivel de la UE — ViDA (2025–2035)', 'Esta página de análisis refleja la orientación oficial de la Comisión Europea sobre ViDA y la norma EN 16931-1:2026 del CEN a partir de agosto de 2026, y se proporciona con fines informativos generales, no como asesoramiento legal o fiscal. ViDA establece un marco a nivel de la UE, no sustituye ni anula el mandato nacional de facturación electrónica de ningún Estado miembro. Consulte las páginas específicas de cada país en el tracker para saber qué es realmente obligatorio en el mercado donde factura hoy, y confirme los desarrollos actuales directamente con la Dirección General de Fiscalidad y Unión Aduanera de la Comisión Europea antes de tomar decisiones de infraestructura.', 'ViDA no es un único plazo: son tres pilares que entran en vigor en tres calendarios distintos entre 2025 y 2035, superpuestos al mandato doméstico que ya aplique su propio Estado miembro.', 'ViDA estandariza el modelo de datos, no una única red de transmisión nacional: EN 16931 define qué debe contener una factura electrónica conforme, no cómo debe entregarla cada Estado miembro.', 'Esta página cubre el marco ViDA a nivel de la UE en sí mismo, no el mandato doméstico de ningún país en particular. ViDA se basa en tres pilares que avanzan en calendarios distintos: Requisitos de Reporte Digital en tiempo real para el comercio B2B transfronterizo (desde 2030), normas de IVA actualizadas para la economía de plataformas (desde 2028), y un modelo de Registro Único de IVA que amplía la Ventanilla Única ya existente (escalonado desde 2027). Consulte las páginas específicas de cada país en el tracker — Italia, Bélgica, Polonia y otros — para saber qué es realmente obligatorio en el mercado donde factura hoy.', 'Lo que realmente debe hacer depende de qué pilar le afecta y cuándo: una plataforma de alquiler de corta duración que se prepara para 2028 tiene una lista de verificación distinta a la de un comerciante B2B transfronterizo que se prepara para 2030.', 'ViDA en sí mismo no establece un régimen sancionador: la aplicación sigue siendo competencia nacional, por lo que las sanciones por incumplimiento tendrán la forma que ya aplique (o introduzca) su propio Estado miembro para su mandato doméstico.' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Gestaffelter EU-weiter Rahmen — ViDA (2025–2035)', 'Diese Detailseite spiegelt die offiziellen ViDA-Hinweise der Europäischen Kommission und den CEN-Standard EN 16931-1:2026 mit Stand August 2026 wider und dient allgemeinen Informationszwecken, nicht der Rechts- oder Steuerberatung. ViDA schafft einen EU-weiten Rahmen — es ersetzt oder überlagert nicht das eigene inländische E-Invoicing-Mandat eines einzelnen Mitgliedstaats. Prüfen Sie die länderspezifischen Seiten im Tracker, um zu erfahren, was in dem Markt, in dem Sie heute fakturieren, tatsächlich verpflichtend ist, und bestätigen Sie aktuelle Entwicklungen direkt bei der Generaldirektion Steuern und Zollunion der Europäischen Kommission, bevor Sie Infrastrukturentscheidungen treffen.', 'ViDA ist kein einzelner Stichtag — es sind drei Säulen, die zwischen 2025 und 2035 nach drei unterschiedlichen Zeitplänen in Kraft treten, aufgesetzt auf das inländische Mandat, das Ihr eigener Mitgliedstaat bereits betreibt.', 'ViDA standardisiert das Datenmodell, nicht ein einziges nationales Übertragungsnetz — EN 16931 definiert, was eine konforme E-Rechnung enthalten muss, nicht wie jeder Mitgliedstaat sie zustellen muss.', 'Diese Seite behandelt den EU-weiten ViDA-Rahmen selbst, nicht das inländische Mandat eines einzelnen Landes. ViDA basiert auf drei Säulen mit unterschiedlichen Zeitplänen: Echtzeit-Digitalmeldepflichten für grenzüberschreitenden B2B-Handel (ab 2030), aktualisierte Mehrwertsteuerregeln für die Plattformwirtschaft (ab 2028) und ein Modell der einheitlichen USt-Registrierung, das den bestehenden One-Stop-Shop erweitert (gestaffelt ab 2027). Prüfen Sie die länderspezifischen Seiten im Tracker — Italien, Belgien, Polen und andere —, um zu erfahren, was in dem Markt, in dem Sie heute fakturieren, tatsächlich verpflichtend ist.', 'Was tatsächlich zu tun ist, hängt davon ab, welche Säule Sie betrifft und wann — eine Kurzzeitvermietungsplattform, die sich auf 2028 vorbereitet, hat eine andere Checkliste als ein grenzüberschreitender B2B-Händler, der sich auf 2030 vorbereitet.', 'ViDA selbst legt keinen Sanktionskatalog fest — die Durchsetzung bleibt nationale Zuständigkeit, sodass Sanktionen bei Nichteinhaltung so aussehen werden, wie es Ihr eigener Mitgliedstaat für sein inländisches Mandat bereits anwendet (oder einführt).' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Cadre échelonné à l''échelle de l''UE — ViDA (2025-2035)', 'Cette page d''analyse reflète les orientations officielles de la Commission européenne sur ViDA et la norme EN 16931-1:2026 du CEN en date d''août 2026, et est fournie à titre informatif général, non comme un avis juridique ou fiscal. ViDA établit un cadre à l''échelle de l''UE — il ne remplace ni ne prime sur le mandat de facturation électronique domestique propre à un État membre. Consultez les pages par pays du tracker pour savoir ce qui est réellement obligatoire sur le marché où vous facturez aujourd''hui, et confirmez les développements actuels directement auprès de la direction générale Fiscalité et Union douanière de la Commission européenne avant de prendre des décisions d''infrastructure.', 'ViDA n''est pas une échéance unique — ce sont trois piliers entrant en vigueur selon trois calendriers distincts entre 2025 et 2035, superposés au mandat domestique déjà en vigueur dans votre propre État membre.', 'ViDA normalise le modèle de données, pas un réseau de transmission national unique — EN 16931 définit ce que doit contenir une facture électronique conforme, pas la façon dont chaque État membre doit la transmettre.', 'Cette page couvre le cadre ViDA à l''échelle de l''UE lui-même, et non le mandat domestique d''un pays particulier. ViDA repose sur trois piliers suivant des calendriers distincts : obligations de déclaration numérique en temps réel pour le commerce B2B transfrontalier (à partir de 2030), règles de TVA actualisées pour l''économie de plateformes (à partir de 2028), et un modèle d''immatriculation unique à la TVA élargissant le guichet unique existant (échelonné à partir de 2027). Consultez les pages par pays du tracker — Italie, Belgique, Pologne et autres — pour savoir ce qui est réellement obligatoire sur le marché où vous facturez aujourd''hui.', 'Ce qu''il convient réellement de faire dépend du pilier qui vous concerne, et à quel moment — une plateforme de location de courte durée se préparant à 2028 n''a pas la même liste de vérification qu''un commerçant B2B transfrontalier se préparant à 2030.', 'ViDA lui-même ne fixe pas de barème de sanctions — l''application reste une compétence nationale, de sorte que les sanctions en cas de non-conformité prendront la forme de celles déjà appliquées (ou introduites) par votre propre État membre pour son mandat domestique.' FROM countries WHERE name_en = 'European Union';

