INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'EN 16931 — la columna vertebral semántica', '[["Norma original", "Adoptada bajo la Directiva 2014/55/UE, centrada en la facturación B2G"], ["Revisión de 2026", "EN 16931-1:2026, aprobada por el CEN el 13 de febrero de 2026, publicada el 18 de marzo de 2026"]]', 'EN 16931 define un modelo de datos semántico común para los elementos esenciales de una factura electrónica — un vocabulario compartido, no un único formato de archivo — garantizando la interoperabilidad en todos los Estados miembros de la UE.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'La revisión de 2026, en detalle', '[["Nuevos campos", "IBAN, indicadores de triangulación, secuenciación de facturas rectificativas, soporte para regímenes de margen de beneficio"], ["Propósito", "Preparar la norma de la era B2G para escenarios B2B complejos y transfronterizos de ViDA"]]', 'Esta revisión es lo que hace que EN 16931 sea apta para su propósito antes de 2030 — la norma original se redactó para casos de uso B2G y necesitaba una ampliación real para soportar el tráfico de los Requisitos de Reporte Digital B2B a escala de la UE.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formato frente a mandato: dos cosas distintas', '[["Lo que define ViDA", "El modelo de datos EN 16931 que debe cumplir una factura electrónica conforme"], ["Lo que ViDA no define", "Una única red de transmisión o modelo de compensación a nivel de toda la UE"]]', 'No confunda ambos conceptos: ViDA establece el estándar de datos de destino, pero deja que cada Estado miembro (o relación comercial) elija el canal de transmisión — Peppol, una plataforma doméstica o un intercambio directo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Estructurado significa legible por máquina, no un formato de archivo específico', '[["Sintaxis conformes", "UBL y CII son las dos sintaxis base que EN 16931 admite formalmente"], ["Implementación habitual", "Peppol BIS Billing 3.0, el perfil conforme con EN 16931 más adoptado en toda la UE"]]', '"Conforme con EN 16931" es un requisito de contenido semántico, no un formato de archivo con nombre único — la mayoría de las empresas de la UE lo cumplen hoy a través de Peppol BIS Billing 3.0, pero cualquier implementación UBL o CII del mismo modelo de datos también es válida.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'EN 16931 — das semantische Rückgrat', '[["Ursprüngliche Norm", "Angenommen unter Richtlinie 2014/55/EU, mit Fokus auf B2G-E-Invoicing"], ["Überarbeitung 2026", "EN 16931-1:2026, vom CEN am 13. Februar 2026 genehmigt, am 18. März 2026 veröffentlicht"]]', 'EN 16931 definiert ein gemeinsames semantisches Datenmodell für die Kernelemente einer E-Rechnung — ein gemeinsames Vokabular, kein einzelnes Dateiformat —, das die Interoperabilität in allen EU-Mitgliedstaaten sicherstellt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die Überarbeitung 2026 im Detail', '[["Neue Felder", "IBAN, Dreiecksgeschäft-Indikatoren, Rechnungskorrektur-Sequenzierung, Unterstützung für Differenzbesteuerung"], ["Zweck", "Den aus der B2G-Ära stammenden Standard für komplexe B2B- und grenzüberschreitende ViDA-Szenarien zukunftssicher machen"]]', 'Diese Überarbeitung macht EN 16931 fit für den Zweck vor 2030 — der ursprüngliche Standard wurde für B2G-Anwendungsfälle geschrieben und benötigte eine echte Erweiterung, um den EU-weiten B2B-Digitalmeldepflicht-Verkehr abzuwickeln.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Format versus Mandat — zwei verschiedene Dinge', '[["Was ViDA definiert", "Das EN-16931-Datenmodell, das eine konforme E-Rechnung erfüllen muss"], ["Was ViDA nicht definiert", "Ein einziges EU-weites Übertragungsnetz oder Clearing-Modell"]]', 'Verwechseln Sie die beiden nicht: ViDA legt den Ziel-Datenstandard fest, überlässt es aber jedem Mitgliedstaat (oder jeder Geschäftsbeziehung), den Übertragungskanal zu wählen — Peppol, eine inländische Plattform oder einen direkten Austausch.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Strukturiert bedeutet maschinenlesbar, nicht eine bestimmte Syntax', '[["Konforme Syntaxen", "UBL und CII sind die beiden Basissyntaxen, die EN 16931 formal unterstützt"], ["Gängige Umsetzung", "Peppol BIS Billing 3.0, das in der EU am weitesten verbreitete EN-16931-konforme Profil"]]', '"EN-16931-konform" ist eine Anforderung an den semantischen Inhalt, kein einzelnes benanntes Dateiformat — die meisten EU-Unternehmen erfüllen dies heute über Peppol BIS Billing 3.0, aber jede UBL- oder CII-Umsetzung desselben Datenmodells erfüllt die Anforderung ebenfalls.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'EN 16931 — l''épine dorsale sémantique', '[["Norme initiale", "Adoptée en vertu de la directive 2014/55/UE, axée sur la facturation B2G"], ["Révision 2026", "EN 16931-1:2026, approuvée par le CEN le 13 février 2026, publiée le 18 mars 2026"]]', 'EN 16931 définit un modèle de données sémantique commun pour les éléments essentiels d''une facture électronique — un vocabulaire partagé, pas un format de fichier unique — garantissant l''interopérabilité dans tous les États membres de l''UE.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'La révision 2026, en détail', '[["Nouveaux champs", "IBAN, indicateurs de triangulation, séquentialisation des factures rectificatives, prise en charge des régimes de la marge"], ["Objectif", "Pérenniser la norme héritée de l''ère B2G pour les scénarios B2B complexes et transfrontaliers de ViDA"]]', 'Cette révision est ce qui rend EN 16931 apte à l''usage avant 2030 — la norme initiale avait été rédigée pour des cas d''usage B2G et nécessitait une réelle extension pour porter le trafic des obligations de déclaration numérique B2B à l''échelle de l''UE.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Format contre mandat — deux choses distinctes', '[["Ce que ViDA définit", "Le modèle de données EN 16931 qu''une facture électronique conforme doit respecter"], ["Ce que ViDA ne définit pas", "Un réseau de transmission unique ou un modèle de contrôle à l''échelle de toute l''UE"]]', 'Ne confondez pas les deux : ViDA fixe la norme de données de destination, mais laisse à chaque État membre (ou relation commerciale) le choix du canal de transmission — Peppol, une plateforme domestique ou un échange direct.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Structuré signifie lisible par machine, pas une syntaxe spécifique', '[["Syntaxes conformes", "UBL et CII sont les deux syntaxes de base formellement prises en charge par EN 16931"], ["Mise en œuvre courante", "Peppol BIS Billing 3.0, le profil conforme à EN 16931 le plus largement adopté dans l''UE"]]', '« Conforme à EN 16931 » est une exigence de contenu sémantique, pas un format de fichier unique nommé — la plupart des entreprises de l''UE y répondent aujourd''hui via Peppol BIS Billing 3.0, mais toute mise en œuvre UBL ou CII du même modèle de données est également valable.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Tres pilares, tres calendarios', '[["Requisitos de Reporte Digital (DRR)", "Facturación electrónica B2B transfronteriza + reporte casi en tiempo real desde el 1 de julio de 2030"], ["Economía de plataformas", "Normas de proveedor considerado para alquiler de corta duración y transporte por carretera desde el 1 de julio de 2028"], ["Registro Único de IVA (SVR)", "Alcance ampliado de OSS/IOSS, escalonado desde el 1 de enero de 2027"]]', 'Estos tres pilares se adoptaron juntos como un único paquete el 11 de marzo de 2025, pero entran en vigor en fechas realmente distintas: trátelos como tres proyectos de cumplimiento independientes, no como uno solo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Mandatos domésticos hoy frente a la capa transfronteriza de 2030', '[["Doméstico", "Varios Estados miembros (Italia, Bélgica, Polonia, Francia y otros) ya aplican, o están introduciendo, sus propios mandatos B2B domésticos vinculantes, bajo excepciones disponibles desde la entrada en vigor de ViDA en abril de 2025"], ["Transfronterizo", "Los propios Requisitos de Reporte Digital de ViDA a nivel de la UE se aplican específicamente a las transacciones B2B transfronterizas intracomunitarias desde julio de 2030, como una capa independiente"]]', 'Una empresa ya puede estar legalmente obligada a facturar electrónicamente a nivel doméstico hoy en un Estado miembro, mientras que la capa transfronteriza a nivel de la UE para el comercio intracomunitario de esa misma empresa no llega hasta 2030 — ambas son reales y funcionan con calendarios distintos.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'La convergencia de 2035', '[["Quién se ve afectado", "Los Estados miembros con un sistema doméstico de reporte de transacciones en tiempo real ya implantado antes del 1 de enero de 2024 (p. ej., el SDI de Italia)"], ["Qué cambia", "Esos sistemas domésticos preexistentes deben alinearse con la norma y el modelo armonizados de la UE bajo ViDA antes del 1 de enero de 2035"]]', 'Esta es la línea de meta de todo el paquete ViDA — para 2035, incluso los sistemas nacionales de compensación más antiguos y consolidados de la UE deben converger en el mismo estándar basado en EN 16931 que todos los demás.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Drei Säulen, drei Zeitpläne', '[["Digitale Meldepflichten (DRR)", "Grenzüberschreitendes B2B-E-Invoicing + Nahezu-Echtzeit-Meldung ab 1. Juli 2030"], ["Plattformwirtschaft", "Regeln zum fiktiven Lieferer für Kurzzeitvermietung und Straßenverkehr ab 1. Juli 2028"], ["Einheitliche USt-Registrierung (SVR)", "Erweiterter OSS-/IOSS-Anwendungsbereich, gestaffelt ab 1. Januar 2027"]]', 'Diese drei Säulen wurden am 11. März 2025 gemeinsam als ein einziges Paket verabschiedet, treten aber zu wirklich unterschiedlichen Zeitpunkten in Kraft — behandeln Sie sie als drei separate Compliance-Projekte, nicht als eines.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Inländische Mandate heute versus die grenzüberschreitende 2030-Ebene', '[["Inländisch", "Mehrere Mitgliedstaaten (Italien, Belgien, Polen, Frankreich und andere) betreiben bereits eigene verbindliche inländische B2B-Mandate oder führen diese ein, unter Ausnahmen, die seit dem Inkrafttreten von ViDA im April 2025 verfügbar sind"], ["Grenzüberschreitend", "ViDAs eigene EU-weite Digitale Meldepflichten gelten speziell für grenzüberschreitende innergemeinschaftliche B2B-Transaktionen ab Juli 2030, als separate Ebene"]]', 'Ein Unternehmen kann bereits heute in einem Mitgliedstaat rechtlich zur inländischen E-Rechnungsstellung verpflichtet sein, während die EU-weite grenzüberschreitende Ebene für den innergemeinschaftlichen Handel desselben Unternehmens erst 2030 kommt — beides ist real, und beides läuft nach unterschiedlichen Uhren.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die Konvergenz 2035', '[["Wer betroffen ist", "Mitgliedstaaten mit einem bereits vor dem 1. Januar 2024 bestehenden inländischen Echtzeit-Transaktionsmeldesystem (z. B. Italiens SDI)"], ["Was sich ändert", "Diese bereits bestehenden inländischen Systeme müssen bis zum 1. Januar 2035 an den harmonisierten EU-ViDA-Standard und das Modell angeglichen werden"]]', 'Dies ist die Ziellinie des gesamten ViDA-Pakets — bis 2035 müssen selbst die ältesten und etabliertesten nationalen Clearing-Systeme der EU auf denselben EN-16931-basierten Standard wie alle anderen konvergieren.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Trois piliers, trois calendriers', '[["Obligations de déclaration numérique (DRR)", "Facturation électronique B2B transfrontalière + déclaration quasi en temps réel à partir du 1er juillet 2030"], ["Économie de plateformes", "Règles de fournisseur présumé pour la location de courte durée et le transport routier à partir du 1er juillet 2028"], ["Immatriculation unique à la TVA (SVR)", "Champ élargi de l''OSS/IOSS, échelonné à partir du 1er janvier 2027"]]', 'Ces trois piliers ont été adoptés ensemble sous la forme d''un paquet unique le 11 mars 2025, mais ils entrent en vigueur à des dates réellement différentes — traitez-les comme trois projets de conformité distincts, et non comme un seul.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Mandats domestiques actuels contre la couche transfrontalière de 2030', '[["Domestique", "Plusieurs États membres (Italie, Belgique, Pologne, France et autres) appliquent déjà — ou introduisent — leurs propres mandats B2B domestiques contraignants, en vertu de dérogations disponibles depuis l''entrée en vigueur de ViDA en avril 2025"], ["Transfrontalier", "Les propres obligations de déclaration numérique de ViDA à l''échelle de l''UE s''appliquent spécifiquement aux transactions B2B transfrontalières intracommunautaires à partir de juillet 2030, en tant que couche distincte"]]', 'Une entreprise peut déjà être légalement tenue de facturer électroniquement au niveau domestique aujourd''hui dans un État membre, tandis que la couche transfrontalière à l''échelle de l''UE pour le commerce intracommunautaire de cette même entreprise n''arrive qu''en 2030 — les deux sont réelles, et fonctionnent selon des calendriers différents.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'La convergence de 2035', '[["Qui est concerné", "Les États membres disposant d''un système domestique de déclaration des transactions en temps réel déjà en place avant le 1er janvier 2024 (par exemple, le SDI italien)"], ["Ce qui change", "Ces systèmes domestiques préexistants doivent s''aligner sur la norme et le modèle harmonisés de l''UE au titre de ViDA d''ici le 1er janvier 2035"]]', 'C''est la ligne d''arrivée de l''ensemble du paquet ViDA — d''ici 2035, même les systèmes nationaux de contrôle les plus anciens et les plus établis de l''UE doivent converger vers la même norme fondée sur EN 16931 que tous les autres.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Identifique cada Estado miembro donde tenga obligaciones de IVA', 'Enumere cada país de la UE en el que esté registrado a efectos del IVA o donde opere, y siga el calendario propio de facturación electrónica/excepción doméstica de ese país por separado de las fechas de ViDA a nivel de la UE — muchos ya van por delante de 2030.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que sus sistemas ERP/CxP pueden generar facturas electrónicas conformes con EN 16931-1:2026', 'Esto implica cubrir el conjunto de campos ampliado de la revisión de 2026 — IBAN, indicadores de triangulación, secuenciación de facturas rectificativas y soporte para regímenes de margen de beneficio — no solo la norma original de la era B2G.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si comercia B2B transfronterizo dentro de la UE, prepárese para la capa DRR de 2030', 'Avance hacia la emisión de facturas electrónicas conformes con EN 16931 dentro de los 10 días posteriores al hecho imponible y el reporte casi en tiempo real, antes de la entrada en vigor el 1 de julio de 2030 para las transacciones B2B intracomunitarias.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si opera una plataforma que entra en el ámbito de aplicación o suministra en Estados donde no está registrado, revise los cambios de 2028', 'Las plataformas de alquiler de alojamiento de corta duración y de transporte de pasajeros por carretera asumen obligaciones de IVA como proveedor considerado desde el 1 de julio de 2028; los proveedores no establecidos y no registrados a efectos del IVA también pueden quedar sujetos a una nueva inversión del sujeto pasivo obligatoria.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si ya opera bajo un sistema de compensación doméstico, siga su plan de alineación', 'Las empresas en países con reporte doméstico en tiempo real anterior a 2024 (como el SDI de Italia) deben seguir el plan de su propia autoridad fiscal para converger con la norma armonizada de la UE bajo ViDA antes del plazo del 1 de enero de 2035.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'No espere a 2030 como su única fecha de planificación', 'Varios Estados miembros ya cuentan con — o están introduciendo activamente — sus propios mandatos domésticos vinculantes mucho antes de la capa transfronteriza a nivel de la UE. Consulte las páginas específicas de cada país en este tracker, no solo este resumen a nivel de la UE.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Erfassen Sie jeden Mitgliedstaat, in dem Sie umsatzsteuerliche Pflichten haben', 'Listen Sie jedes EU-Land auf, in dem Sie umsatzsteuerlich registriert sind oder Handel treiben, und verfolgen Sie den eigenen E-Invoicing-/Ausnahme-Zeitplan dieses Landes getrennt von den unten stehenden EU-weiten ViDA-Terminen — viele sind bereits weiter als 2030.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Stellen Sie sicher, dass Ihre ERP-/Kreditorensysteme EN-16931-1:2026-konforme E-Rechnungen erstellen können', 'Das bedeutet, den erweiterten Feldsatz der Überarbeitung 2026 abzudecken — IBAN, Dreiecksgeschäft-Indikatoren, Rechnungskorrektur-Sequenzierung und Unterstützung für Differenzbesteuerung — nicht nur den ursprünglichen Standard aus der B2G-Ära.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie grenzüberschreitend B2B innerhalb der EU handeln, bereiten Sie sich auf die DRR-Ebene 2030 vor', 'Arbeiten Sie darauf hin, EN-16931-konforme E-Rechnungen innerhalb von 10 Tagen nach dem Steuertatbestand auszustellen und nahezu in Echtzeit zu melden, vor dem Start am 1. Juli 2030 für innergemeinschaftliche B2B-Transaktionen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie eine betroffene Plattform betreiben oder in Staaten liefern, in denen Sie nicht registriert sind, prüfen Sie die Änderungen 2028', 'Plattformen für Kurzzeitvermietung und Personenstraßenverkehr übernehmen ab dem 1. Juli 2028 Pflichten als fiktiver Lieferer bei der Umsatzsteuer; nicht ansässige, nicht umsatzsteuerlich registrierte Lieferer können ebenfalls einem neuen verpflichtenden Reverse-Charge-Verfahren unterliegen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie bereits unter einem inländischen Clearing-System tätig sind, verfolgen Sie dessen Angleichungsplan', 'Unternehmen in Ländern mit inländischer Echtzeitmeldung von vor 2024 (wie Italiens SDI) sollten den Plan ihrer eigenen Steuerbehörde zur Konvergenz mit dem harmonisierten EU-ViDA-Standard vor der Frist am 1. Januar 2035 verfolgen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verlassen Sie sich nicht allein auf 2030 als Planungstermin', 'Mehrere Mitgliedstaaten haben bereits eigene verbindliche inländische Mandate — oder führen diese aktiv ein — weit vor der EU-weiten grenzüberschreitenden Ebene. Prüfen Sie die länderspezifischen Seiten dieses Trackers, nicht nur diese EU-weite Zusammenfassung.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Recensez chaque État membre où vous avez des obligations de TVA', 'Dressez la liste de chaque pays de l''UE où vous êtes immatriculé à la TVA ou où vous exercez une activité, et suivez le calendrier propre à ce pays en matière de facturation électronique/dérogation domestique séparément des échéances ViDA à l''échelle de l''UE ci-dessous — beaucoup sont déjà en avance sur 2030.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez que vos systèmes ERP/comptes fournisseurs peuvent produire des factures électroniques conformes à EN 16931-1:2026', 'Cela signifie couvrir l''ensemble de champs élargi de la révision 2026 — IBAN, indicateurs de triangulation, séquentialisation des factures rectificatives et prise en charge des régimes de la marge — et pas seulement la norme initiale de l''ère B2G.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous effectuez du commerce B2B transfrontalier au sein de l''UE, préparez-vous à la couche DRR de 2030', 'Avancez vers l''émission de factures électroniques conformes à EN 16931 dans les 10 jours suivant le fait générateur et vers une déclaration quasi en temps réel, avant l''entrée en vigueur le 1er juillet 2030 pour les transactions B2B intracommunautaires.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous exploitez une plateforme concernée ou fournissez dans des États où vous n''êtes pas immatriculé, examinez les changements de 2028', 'Les plateformes de location de courte durée et de transport routier de voyageurs assument des obligations de TVA en tant que fournisseur présumé à partir du 1er juillet 2028 ; les fournisseurs non établis et non immatriculés à la TVA peuvent également être soumis à une nouvelle autoliquidation obligatoire.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous opérez déjà sous un système de contrôle domestique, suivez son plan d''alignement', 'Les entreprises des pays disposant d''une déclaration domestique en temps réel antérieure à 2024 (comme le SDI italien) doivent suivre le plan de leur propre administration fiscale pour converger vers la norme harmonisée de l''UE au titre de ViDA avant l''échéance du 1er janvier 2035.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Ne comptez pas uniquement sur 2030 comme date de planification', 'Plusieurs États membres disposent déjà — ou introduisent activement — leurs propres mandats domestiques contraignants bien avant la couche transfrontalière à l''échelle de l''UE. Consultez les pages par pays de ce tracker, pas seulement ce résumé à l''échelle de l''UE.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'European Union' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💶 La reducción del fraude es el argumento económico principal', NULL, NULL, 'La Comisión Europea estima que el reporte digital en tiempo real podría reducir el fraude del IVA hasta en 11.000 millones de euros al año, a la vez que reduciría los costes administrativos y de cumplimiento de las empresas de la UE en más de 4.100 millones de euros al año durante la década siguiente — la justificación central de todo el paquete.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '⚖️ ViDA establece el marco, no las sanciones', NULL, NULL, 'ViDA en sí mismo no crea un régimen sancionador a nivel de la UE por incumplimiento: la aplicación y las sanciones siguen siendo competencia nacional, por lo que cabe esperar estructuras sancionadoras con la forma que ya aplique su propio Estado miembro para su mandato doméstico (consulte la página de ese país en el tracker).', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🧩 Un mosaico de 27 Estados miembros, por diseño', NULL, NULL, 'Los pilares escalonados de ViDA coexisten deliberadamente con los mandatos domésticos de los Estados miembros en lugar de sustituirlos por completo — el marco hace converger a todos hacia la misma norma con el tiempo (para 2035), pero el camino hasta allí atraviesa 27 calendarios nacionales distintos.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔜 El rumbo está fijado incluso donde la fecha no lo está', NULL, NULL, 'Incluso en los Estados miembros sin un mandato doméstico ya definido, ViDA fija el formato de destino EN 16931 en todo el bloque — la pregunta abierta para la mayoría de las empresas no es si viene la facturación electrónica estructurada, sino en qué año aterriza en su propio país.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💶 Betrugsreduktion ist das wirtschaftliche Hauptargument', NULL, NULL, 'Die Europäische Kommission schätzt, dass Echtzeit-Digitalmeldung den Mehrwertsteuerbetrug um bis zu 11 Milliarden Euro pro Jahr senken könnte, während gleichzeitig die Verwaltungs- und Compliance-Kosten für EU-Händler in den folgenden zehn Jahren um mehr als 4,1 Milliarden Euro pro Jahr sinken würden — die zentrale Begründung für das gesamte Paket.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '⚖️ ViDA legt den Rahmen fest, nicht die Sanktionen', NULL, NULL, 'ViDA selbst schafft keinen EU-weiten Sanktionskatalog für Nichteinhaltung — Durchsetzung und Bußgelder bleiben nationale Zuständigkeit, sodass mit Sanktionsstrukturen zu rechnen ist, die so aussehen wie das, was Ihr eigener Mitgliedstaat für sein inländisches Mandat bereits anwendet (siehe die entsprechende Länderseite im Tracker).', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🧩 Ein Flickenteppich aus 27 Mitgliedstaaten — mit Absicht', NULL, NULL, 'ViDAs gestaffelte Säulen koexistieren bewusst mit den eigenen inländischen Mandaten der Mitgliedstaaten, anstatt sie vollständig zu ersetzen — der Rahmen führt letztlich alle zum selben Standard zusammen (bis 2035), aber der Weg dorthin verläuft über 27 unterschiedliche nationale Zeitpläne.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔜 Die Richtung steht fest, auch wenn das Datum es nicht tut', NULL, NULL, 'Selbst in Mitgliedstaaten ohne bereits festgelegtes inländisches Mandat legt ViDA das Zielformat EN 16931 für den gesamten Block fest — die offene Frage für die meisten Unternehmen ist nicht, ob strukturiertes E-Invoicing kommt, sondern in welchem Jahr es im eigenen Land ankommt.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💶 La réduction de la fraude est l''argument économique phare', NULL, NULL, 'La Commission européenne estime que la déclaration numérique en temps réel pourrait réduire la fraude à la TVA jusqu''à 11 milliards d''euros par an, tout en réduisant les coûts administratifs et de conformité des entreprises de l''UE de plus de 4,1 milliards d''euros par an au cours de la décennie suivante — la justification centrale de l''ensemble du paquet.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '⚖️ ViDA fixe le cadre, pas les sanctions', NULL, NULL, 'ViDA lui-même ne crée aucun barème de sanctions à l''échelle de l''UE en cas de non-conformité — l''application et les amendes restent une compétence nationale ; attendez-vous donc à des structures de sanctions à l''image de celles déjà appliquées (ou introduites) par votre propre État membre pour son mandat domestique (voir la page de ce pays dans le tracker).', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🧩 Une mosaïque de 27 États membres, par construction', NULL, NULL, 'Les piliers échelonnés de ViDA coexistent délibérément avec les mandats domestiques des États membres plutôt que de les remplacer entièrement — le cadre fait converger tout le monde vers la même norme à terme (d''ici 2035), mais le chemin pour y parvenir traverse 27 calendriers nationaux distincts.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔜 La direction est fixée même quand la date ne l''est pas', NULL, NULL, 'Même dans les États membres sans mandat domestique encore finalisé, ViDA verrouille le format de destination EN 16931 pour l''ensemble du bloc — la question ouverte pour la plupart des entreprises n''est pas de savoir si la facturation électronique structurée arrive, mais en quelle année elle arrivera dans leur propre pays.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'European Union' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

